export function createPgRingGeometry(cx,cz){
 const clean=points=>{const a=points.map(p=>p.clone());if(a.length>1&&a[0].equals(a.at(-1)))a.pop();return a;};
 const orient=(a,cw)=>{if(T.ShapeUtils.isClockWise(a)!==cw)a.reverse();return a;};
 const s=new T.Shape(),r=2.4,h=21;
 s.moveTo(-h+r,-h);s.lineTo(h-r,-h);s.quadraticCurveTo(h,-h,h,-h+r);s.lineTo(h,h-r);s.quadraticCurveTo(h,h,h-r,h);s.lineTo(-h+r,h);s.quadraticCurveTo(-h,h,-h,h-r);s.lineTo(-h,-h+r);s.quadraticCurveTo(-h,-h,-h+r,-h);
 const outer=orient(clean(s.getPoints(48)),false),holes=[];
 for(const[x,z]of[[-15.5,-15.5],[15.5,-15.5],[-15.5,15.5],[15.5,15.5]]){const p=new T.Path();p.absarc(x,z,1.7,0,2*Math.PI,false);holes.push(orient(clean(p.getPoints(48)),true));}
 const full=orient(ringCavity.map(([x,z])=>new T.Vector2(x,z)),true),lead=full.map(p=>p.clone().multiplyScalar(1+.3/p.length())),xyz=[];
 const tri=(a,b,c)=>xyz.push(...a,...b,...c);
 const cap=(hs,z,up)=>{const loops=[clean(outer),...hs.map(clean)],pts=loops.flat(),faces=T.ShapeUtils.triangulateShape(loops[0],loops.slice(1));for(const f of faces){let[a,b,c]=f.map(i=>pts[i]);if(((b.x-a.x)*(c.y-a.y)-(b.y-a.y)*(c.x-a.x)>0)!==up)[b,c]=[c,b];tri([a.x,a.y,z],[b.x,b.y,z],[c.x,c.y,z]);}};
 const wall=(lo,hi,z0,z1)=>{for(let i=0;i<lo.length;i++){const k=(i+1)%lo.length,a=lo[i],b=lo[k],c=hi[k],d=hi[i];tri([a.x,a.y,z0],[b.x,b.y,z0],[c.x,c.y,z1]);tri([a.x,a.y,z0],[c.x,c.y,z1],[d.x,d.y,z1]);}};
 cap([...holes,lead],0,false);cap([...holes,full],4.8,true);wall(outer,outer,0,4.8);holes.forEach(h=>wall(h,h,0,4.8));wall(lead,full,0,.3);wall(full,full,.3,4.8);
 const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(xyz,3));g.computeVertexNormals();g.applyMatrix4(new T.Matrix4().set(.001,0,0,cx/1000,0,0,-.001,-66.7/1000,0,.001,0,cz/1000,0,0,0,1));return smoothCreases(g);
}
